import{_ as t,c as s,o as a,ag as n}from"./chunks/framework.CoPVQkzc.js";const g=JSON.parse('{"title":"Message Processing","description":"How messages flow through the system","frontmatter":{"title":"Message Processing","description":"How messages flow through the system"},"headers":[],"relativePath":"engine/message_processing.md","filePath":"engine/message_processing.md","lastUpdated":1788476353000}'),r={name:"engine/message_processing.md"};function o(i,e,d,l,c,p){return a(),s("div",null,e[0]||(e[0]=[n(`<h1 id="message-processing" tabindex="-1">Message Processing <a class="header-anchor" href="#message-processing" aria-label="Permalink to &quot;Message Processing&quot;">​</a></h1><p>This page covers how data moves through an OIE channel, from initial receipt through transformation and delivery.</p><h2 id="about-message-data" tabindex="-1">About message data <a class="header-anchor" href="#about-message-data" aria-label="Permalink to &quot;About message data&quot;">​</a></h2><p>A <strong>message</strong> in OIE represents one complete unit of data traveling through a channel&#39;s source and destinations. Each message is broken down into individual <strong>connector messages</strong>, one per connector it passes through. So a channel with a source and two destinations generates three connector messages for every inbound message.</p><p>It is important to note that a single inbound payload does not necessarily equal a single message. If the source connector&#39;s batch processor is enabled, one incoming file or data stream can be split into many discrete messages. For instance, a file with 100 HL7 v2.x messages could produce either 1 or 100 messages depending on the batch configuration.</p><h2 id="message-metadata" tabindex="-1">Message metadata <a class="header-anchor" href="#message-metadata" aria-label="Permalink to &quot;Message metadata&quot;">​</a></h2><p>Metadata captures key information about each message without including the actual content:</p><ul><li><strong>Message ID</strong>. A unique integer assigned per channel. Used for organizing entries in the Message Browser and linking related connector messages.</li><li><strong>Connector Metadata ID</strong>. A numeric identifier for each connector. The source is always 0, and destinations are numbered starting from 1.</li><li><strong>Status</strong>. Tracks where each connector message stands in the processing pipeline (see <a href="#message-statuses">Message Statuses</a> below).</li><li><strong>Timestamps</strong>. Each connector message records a <strong>received date</strong> (when data was committed to the database). Destinations also track a <strong>send date</strong> and <strong>response date</strong>, which can help diagnose performance and latency.</li><li><strong>Custom Metadata Columns</strong>. User-defined database columns that extract and store selected values from the message, making them visible and searchable in the Message Browser.</li></ul><h2 id="message-content" tabindex="-1">Message content <a class="header-anchor" href="#message-content" aria-label="Permalink to &quot;Message content&quot;">​</a></h2><p>As data travels through a channel, multiple snapshots of it are captured at different stages. Each connector maintains its own set of content versions.</p><h3 id="source-connector-content" tabindex="-1">Source connector content <a class="header-anchor" href="#source-connector-content" aria-label="Permalink to &quot;Source connector content&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Content Type</th><th>Description</th></tr></thead><tbody><tr><td><strong>Raw</strong></td><td>The inbound message after attachment extraction but before any preprocessor modification</td></tr><tr><td><strong>Processed Raw</strong></td><td>The message after the preprocessor script has had a chance to modify it</td></tr><tr><td><strong>Transformed</strong></td><td>The internal (typically XML) representation after serialization. Only present when a filter or transformer is configured</td></tr><tr><td><strong>Encoded</strong></td><td>The final outbound form after deserialization from the internal representation</td></tr><tr><td><strong>Response</strong></td><td>Whatever gets sent back to the originating system once all processing is complete</td></tr></tbody></table><h3 id="destination-connector-content" tabindex="-1">Destination connector content <a class="header-anchor" href="#destination-connector-content" aria-label="Permalink to &quot;Destination connector content&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Content Type</th><th>Description</th></tr></thead><tbody><tr><td><strong>Raw</strong></td><td>The starting data for the destination, which is always a copy of the source&#39;s encoded output</td></tr><tr><td><strong>Transformed</strong></td><td>The internal representation after the destination&#39;s own serialization. Only present when a filter or transformer is configured</td></tr><tr><td><strong>Encoded</strong></td><td>The final outbound form after the destination&#39;s transformer and deserialization</td></tr><tr><td><strong>Sent</strong></td><td>A snapshot of the destination connector properties (dispatch parameters and envelope) captured before the send attempt</td></tr><tr><td><strong>Response</strong></td><td>The reply received back from the external system</td></tr><tr><td><strong>Response Transformed</strong></td><td>The internal representation of the response. Only present when a response transformer is configured</td></tr><tr><td><strong>Processed Response</strong></td><td>The response in its final form after response transformation and deserialization</td></tr></tbody></table><div class="info custom-block"><p class="custom-block-title">INFO</p><p>Each destination receives a copy of the source&#39;s encoded data as its raw input. Destinations do <strong>not</strong> receive data from each other in a daisy-chain fashion. Even with three destinations, every one of them gets the same source encoded output as their starting point.</p></div><h3 id="other-stored-content" tabindex="-1">Other stored content <a class="header-anchor" href="#other-stored-content" aria-label="Permalink to &quot;Other stored content&quot;">​</a></h3><p>The content types above are the message payload at its various stages. The engine persists several other kinds of content alongside them, which is why maps and errors survive to be viewed in the Message Browser long after processing finished:</p><table tabindex="0"><thead><tr><th>Content Type</th><th>Description</th></tr></thead><tbody><tr><td><strong>Source Map</strong></td><td>The source map as it stood for this message</td></tr><tr><td><strong>Connector Map</strong></td><td>The connector map for this connector message</td></tr><tr><td><strong>Channel Map</strong></td><td>The channel map for this message</td></tr><tr><td><strong>Response Map</strong></td><td>The response map, holding responses keyed by destination</td></tr><tr><td><strong>Processing Error</strong></td><td>Errors raised during filtering, transformation, or dispatch</td></tr><tr><td><strong>Postprocessor Error</strong></td><td>Errors raised by the postprocessor script</td></tr><tr><td><strong>Response Error</strong></td><td>Errors raised while handling the destination&#39;s response</td></tr></tbody></table><p>The three error types are stored separately rather than merged, so an error in the postprocessor is distinguishable from one thrown during transformation.</p><h2 id="message-statuses" tabindex="-1">Message statuses <a class="header-anchor" href="#message-statuses" aria-label="Permalink to &quot;Message statuses&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Status</th><th>Meaning</th></tr></thead><tbody><tr><td><strong>RECEIVED</strong></td><td>Data has been persisted but is still being actively processed</td></tr><tr><td><strong>FILTERED</strong></td><td>The message was rejected by a filter and will not continue</td></tr><tr><td><strong>TRANSFORMED</strong></td><td>The transformer has completed successfully; for the source connector this is the final status</td></tr><tr><td><strong>SENT</strong></td><td>The destination successfully dispatched the message</td></tr><tr><td><strong>QUEUED</strong></td><td>The message is waiting in the destination queue, either for initial delivery or retry</td></tr><tr><td><strong>ERROR</strong></td><td>Something went wrong during processing</td></tr><tr><td><strong>PENDING</strong></td><td>The message is waiting to begin processing</td></tr></tbody></table><h2 id="message-lifecycle" tabindex="-1">Message lifecycle <a class="header-anchor" href="#message-lifecycle" aria-label="Permalink to &quot;Message lifecycle&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span> External System</span></span>
<span class="line"><span>       │</span></span>
<span class="line"><span>       ▼</span></span>
<span class="line"><span> ┌─────────────┐</span></span>
<span class="line"><span> │   Source     │  1. Receive raw message</span></span>
<span class="line"><span> │  Connector   │</span></span>
<span class="line"><span> └──────┬──────┘</span></span>
<span class="line"><span>        ▼</span></span>
<span class="line"><span> ┌─────────────┐</span></span>
<span class="line"><span> │ Attachment   │  2. Extract/store attachments (optional)</span></span>
<span class="line"><span> │  Handler     │</span></span>
<span class="line"><span> └──────┬──────┘</span></span>
<span class="line"><span>        ▼</span></span>
<span class="line"><span> ┌─────────────┐</span></span>
<span class="line"><span> │ Preprocessor │  3. Modify raw data before processing (optional)</span></span>
<span class="line"><span> │   Script     │</span></span>
<span class="line"><span> └──────┬──────┘</span></span>
<span class="line"><span>        ▼</span></span>
<span class="line"><span> ┌─────────────┐</span></span>
<span class="line"><span> │   Source     │  4. Filter: accept or reject the message</span></span>
<span class="line"><span> │   Filter     │     Transform: map/modify message content</span></span>
<span class="line"><span> └──────┬──────┘</span></span>
<span class="line"><span>        ▼</span></span>
<span class="line"><span> ┌─────────────┐</span></span>
<span class="line"><span> │ Destination  │  5. Each destination gets a copy of the source encoded data</span></span>
<span class="line"><span> │  Filter(s)   │     Destination filter: route to specific destinations</span></span>
<span class="line"><span> └──────┬──────┘</span></span>
<span class="line"><span>        ▼</span></span>
<span class="line"><span> ┌─────────────┐</span></span>
<span class="line"><span> │ Destination  │  6. Transform message for the specific destination</span></span>
<span class="line"><span> │ Transformer  │</span></span>
<span class="line"><span> └──────┬──────┘</span></span>
<span class="line"><span>        ▼</span></span>
<span class="line"><span> ┌─────────────┐</span></span>
<span class="line"><span> │ Destination  │  7. Send to external system</span></span>
<span class="line"><span> │  Connector   │</span></span>
<span class="line"><span> └──────┬──────┘</span></span>
<span class="line"><span>        ▼</span></span>
<span class="line"><span> ┌─────────────┐</span></span>
<span class="line"><span> │ Response     │  8. Process response from destination (optional)</span></span>
<span class="line"><span> │ Transformer  │</span></span>
<span class="line"><span> └──────┬──────┘</span></span>
<span class="line"><span>        ▼</span></span>
<span class="line"><span> ┌──────────────┐</span></span>
<span class="line"><span> │ Postprocessor │  9. Final processing after all destinations complete</span></span>
<span class="line"><span> │   Script      │</span></span>
<span class="line"><span> └───────────────┘</span></span></code></pre></div><h2 id="source-processing-steps" tabindex="-1">Source processing steps <a class="header-anchor" href="#source-processing-steps" aria-label="Permalink to &quot;Source processing steps&quot;">​</a></h2><ol><li>The source connector receives an inbound message or data stream.</li><li>If the batch processor is active, the data may be divided into multiple messages. The remaining steps repeat for each one.</li><li>The attachment handler runs, pulling out and separately storing any attachment content.</li><li>What remains is saved as the <em>raw</em> data.</li><li>The preprocessor script runs, and its output is saved as the <em>processed raw</em> data.</li><li>The processed raw data is serialized into the <strong>inbound data type&#39;s</strong> internal format (usually XML).</li><li>Filters evaluate the message. If it is rejected, processing skips ahead to the Final Processing Steps.</li><li>The transformer modifies the data as needed.</li><li>The result is saved as the <em>transformed</em> data.</li><li>The data is deserialized from the <strong>outbound data type&#39;s</strong> internal format back into a concrete format (e.g., HL7, EDI).</li><li>This output is saved as the <em>encoded</em> data.</li></ol><div class="info custom-block"><p class="custom-block-title">INFO</p><p>When no filter or transformer is present, no transformed or encoded content will exist. The raw (or processed raw) data carries forward directly.</p></div><ol start="12"><li>The encoded data is handed off to the first destination connector in each destination chain.</li></ol><h2 id="destination-processing-steps" tabindex="-1">Destination processing steps <a class="header-anchor" href="#destination-processing-steps" aria-label="Permalink to &quot;Destination processing steps&quot;">​</a></h2><p>These steps run independently for every destination connector the message reaches.</p><ol><li>The destination starts with the source&#39;s encoded output as its <strong>raw</strong> data.</li><li>This raw data is serialized into the <strong>inbound data type&#39;s</strong> internal format.</li><li>Filters evaluate the message. If rejected, processing stops for this destination. If other destinations remain in the chain, they continue. Once all chains finish, the Final Processing Steps run.</li><li>The transformer modifies the data as needed.</li><li>The result is saved as <strong>transformed</strong> data.</li><li>The data is deserialized from the <strong>outbound data type&#39;s</strong> internal format into the final outbound format.</li><li>This output is saved as <strong>encoded</strong> data.</li></ol><div class="info custom-block"><p class="custom-block-title">INFO</p><p>When no filter or transformer is present, no transformed or encoded content will exist. The raw data carries forward directly.</p></div><ol start="8"><li>The destination connector captures a snapshot of its dispatch properties as <strong>sent</strong> data, then dispatches the message to the external system.</li><li>Any reply from the external system is captured as the <strong>response</strong> data.</li><li>If a response transformer is configured, the response is serialized into the <strong>response inbound data type&#39;s</strong> internal format.</li><li>The response transformer runs.</li><li>Its output is saved as <strong>response transformed</strong> data.</li><li>The response is deserialized from the <strong>response outbound data type&#39;s</strong> internal format into its final form.</li><li>This is saved as <strong>processed response</strong> data.</li></ol><h2 id="final-processing-steps" tabindex="-1">Final processing steps <a class="header-anchor" href="#final-processing-steps" aria-label="Permalink to &quot;Final processing steps&quot;">​</a></h2><p>Processing reaches this point once every destination chain has completed, or immediately if the message was filtered or errored at the source level.</p><ol><li>The post processor script runs and may return a response value.</li><li>The source connector selects a response to send back to the originating system. This could be an auto-generated reply, the response from a specific destination, whatever the post processor script returned, or a custom value from the response map.</li><li>The chosen response is saved as the source connector&#39;s <strong>response</strong> data and delivered to the originating system if applicable.</li></ol><h2 id="message-attachments" tabindex="-1">Message attachments <a class="header-anchor" href="#message-attachments" aria-label="Permalink to &quot;Message attachments&quot;">​</a></h2><p>Attachments allow you to separate large or binary content from the message body early in the pipeline. They are tied to the overall message rather than to individual connector messages, and the extraction occurs before even the preprocessor script runs.</p><p>When a destination dispatches data, any stored attachments are automatically spliced back in. Because attachment content is only stored once, rather than being duplicated across each connector&#39;s raw, transformed, and encoded snapshots. This approach can significantly reduce memory consumption.</p><h2 id="message-queuing" tabindex="-1">Message queuing <a class="header-anchor" href="#message-queuing" aria-label="Permalink to &quot;Message queuing&quot;">​</a></h2><p>When a destination has queuing enabled:</p><ol><li>Depending on the queue mode, messages are either placed directly into a <strong>persistent queue</strong> or attempted first and queued on failure</li><li>A background thread retries queued messages at configurable intervals</li><li>Queue settings include: <ul><li><strong>Retry interval</strong> (milliseconds between attempts)</li><li><strong>Rotate queue</strong> (move failed messages to the back of the queue)</li><li><strong>Retry count</strong> (maximum retry attempts before marking as ERROR)</li><li><strong>Thread count</strong> (number of parallel queue processing threads)</li></ul></li></ol><h3 id="queue-modes" tabindex="-1">Queue modes <a class="header-anchor" href="#queue-modes" aria-label="Permalink to &quot;Queue modes&quot;">​</a></h3><p>The <strong>Queue Messages</strong> setting on the destination offers three choices:</p><table tabindex="0"><thead><tr><th>Mode</th><th>Behavior</th></tr></thead><tbody><tr><td><strong>Never</strong></td><td>No queuing. Retries still apply according to the retry count setting</td></tr><tr><td><strong>On Failure</strong></td><td>Attempt an immediate send when the queue is empty, and queue only if that fails</td></tr><tr><td><strong>Always</strong></td><td>Queue first, then send from the queue thread</td></tr></tbody></table><div class="info custom-block"><p class="custom-block-title">INFO</p><p><strong>Queueing depends on the message storage mode.</strong> With storage set to Raw, Metadata, or Disabled, queueing is not supported, and the Administrator shows a warning next to the setting when On Failure or Always is selected. If you need queueing, the channel needs a fuller storage mode.</p></div><p>Additional queue settings on the same panel:</p><table tabindex="0"><thead><tr><th>Setting</th><th>Effect</th></tr></thead><tbody><tr><td><strong>Thread Assignment Variable</strong></td><td>Groups queued messages onto threads by the value of a variable, so related messages keep their relative order. Only available when queueing is on and thread count is above 1</td></tr><tr><td><strong>Regenerate Template</strong></td><td>Rebuilds the destination&#39;s template from the message each time it is sent from the queue, rather than reusing what was built when it was queued</td></tr><tr><td><strong>Include Filter/Transformer</strong></td><td>Re-runs the destination filter and transformer on each queue attempt instead of only on the first</td></tr></tbody></table><h2 id="batch-processing" tabindex="-1">Batch processing <a class="header-anchor" href="#batch-processing" aria-label="Permalink to &quot;Batch processing&quot;">​</a></h2><p>The batch processor lets a source connector break a single inbound payload into many individual messages. When paired with a streaming-capable connector (such as the File Reader or TCP Listener in MLLP mode), this enables processing of very large files (even gigabytes) without loading the entire payload into memory at once.</p><p>To turn on batch processing, set <strong>Process Batch</strong> to <strong>Yes</strong> in the source connector&#39;s settings. The specific splitting behavior is controlled by the <strong>Batch Properties</strong> within the source inbound data type configuration.</p><p>While batch messages are moving through a channel, three additional source map variables become available:</p><ul><li><strong>batchId</strong>. Identifies the overall batch; all messages from the same inbound payload share this value</li><li><strong>batchSequenceId</strong>. A counter starting at 1 that increments with each message in the batch</li><li><strong>batchComplete</strong>. A boolean flag that is true only for the final message in the batch</li></ul>`,52)]))}const u=t(r,[["render",o]]);export{g as __pageData,u as default};
